import{_ as l,a0 as e,w as r,s as h,ao as k,I as t,x as a,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如果使用32位整型会溢出，那么是否可以使用一个40位结构体代替64位长整型？ | LCTT x X-CMD","titleTemplate":false,"description":"如果使用32位整型会溢出，那么是否可以使用一个40位结构体代替64位长整型？ | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如果使用32位整型会溢出，那么是否可以使用一个40位结构体代替64位长整型？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如果使用32位整型会溢出，那么是否可以使用一个40位结构体代替64位长整型？ | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150121 If a 32-bit integer overflows","title":"如果使用32位整型会溢出，那么是否可以使用一个40位结构体代替64位长整型？","tag":"201502","desc":""},"relativePath":"201502/20150121 If a 32-bit integer overflows.md","filePath":"[post].md"}'),o={name:"201502/20150121 If a 32-bit integer overflows.md"};function d(g,s,u,E,c,f){const n=e("Link");return r(),h("div",null,[s[14]||(s[14]=k(`<h1 id="如果使用32位整型会溢出-那么是否可以使用一个40位结构体代替64位长整型" tabindex="-1">如果使用32位整型会溢出，那么是否可以使用一个40位结构体代替64位长整型？ <a class="header-anchor" href="#如果使用32位整型会溢出-那么是否可以使用一个40位结构体代替64位长整型" aria-label="Permalink to “如果使用32位整型会溢出，那么是否可以使用一个40位结构体代替64位长整型？”">​</a></h1><p>###问题：</p><p>假如说，使用32位的整型会溢出，在不考虑使用长整型的情况下，如果我们只需要表示2的40次方范围内的数，是否可以利用某些40位长的数据类型来表示呢？这样的话，每个整型数就可以节省24位的空间。</p><p>如果可以，该怎么做？</p><p>需求是：我现在必须处理数以亿计的数字，所以在存储空间上受到了很大的限制。</p><p>###回答：</p><p>可以是可以，但是……</p><p>这种方法的确可行，但这么做通常没什么意义（因为几乎没有程序需要处理多达十亿的数字）：</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;stdint.h&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 不要考虑使用long long类型</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bad_idea</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> var : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>在这里，变量var占据40位大小，但是这是以生成代码时拥有非常低的运行效率来换取的（事实证明“非常”二字言过其实了——测试中程序开销仅仅增加了1%到2%，正如下面的测试时间所示），而且这么做通常没什么用。除非你还需要保存一个24位的值（或者是8位、16位的值），这样你皆可以它们放到同一个结构中。不然的话，因为对齐内存地址产生的开销会抵消这么做带来的好处。</p><p>在任何情况下，除非你是真的需要保存数以亿计的数字，否则这样做给内存消耗带来的好处是可以忽略不计的（但是为了处理这些位字段的额外代码量是不可忽略的！）。</p><p>###说明：</p><p>在此期间，这个问题已经被更新了，是为了说明实际上确实有需要处理数以亿计数字的情况。假设，采取某些措施来防止因为结构体对齐和填充抵消好处（比如在后24位中存储其它的内容，或者使用多个8位来存储40位），那么这么做就变得有意义了。</p><p>如果有十亿个数，每个数都节省三个字节的空间，那么这么做就非常有用了。因为使用更小的空间存储要求更少的内存页，也就会产生更少的cache和TLB不命中和内存缺页（单个缺页会产生数以千万计的指令 [译者注：直译是这样，但语义说不通！]）。</p><p>尽管上面提到的情况不足以充分利用到剩余的24位（它仅仅使用了40位部分），如果确实在剩余位中放入了有用的数据，那么使用类似下面的方法会使得这种思路就管理内存而言显得非常有用。</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> using_gaps</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> var           : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> useful_uint16 : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> char_or_bool  : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>结构体大小和对齐长度等于64位整型的大小，所以只要使用得当就不会浪费空间，比如对一个保存10亿个数的数组使用这个结构（不考虑使用指定编译器的扩展）。如果你不会用到一个8位的值，那么你可以使用一个48位和16位的值（giving a bigger overflow margin）。</p><p>或者以牺牲可用性为代价，把8个64位的值放入这样的结构体中（或者使用40和64的组合使得其和满足320）。当然，在这种情况下，通过代码去访问数组结构体中的元素会变得非常麻烦（尽管一种方法是实现一个operator[]在功能上还原线性数组，隐藏结构体的复杂性）。</p><p>###更新：</p><p>我写了一个快速测试工具，只是为了获得位字段的开销（以及伴随位字段引用的重载操作）。由于长度限制将代码发布在gcc.godbolt.org上，在本人64位Win7上的测试结果如下：</p><div class="language-TXT"><button title="Copy Code" class="copy"></button><span class="lang">TXT</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>运行测试的数组大小为1048576</span></span>
<span class="line"><span>what       alloc   seq(w)  seq(r)  rand(w)  rand(r)  free</span></span>
<span class="line"><span>-----------------------------------------------------------</span></span>
<span class="line"><span>uint32_t    0      2       1       35       35       1</span></span>
<span class="line"><span>uint64_t    0      3       3       35       35       1</span></span>
<span class="line"><span>bad40_t     0      5       3       35       35       1</span></span>
<span class="line"><span>packed40_t  0      7       4       48       49       1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>运行测试的数组大小为16777216</span></span>
<span class="line"><span>what        alloc  seq(w)  seq(r)  rand(w)  rand(r)  free</span></span>
<span class="line"><span>-----------------------------------------------------------</span></span>
<span class="line"><span>uint32_t    0      38      14      560      555      8</span></span>
<span class="line"><span>uint64_t    0      81      22      565      554      17</span></span>
<span class="line"><span>bad40_t     0      85      25      565      561      16</span></span>
<span class="line"><span>packed40_t  0      151     75      765      774      16</span></span>
<span class="line"><span></span></span>
<span class="line"><span>运行测试的数组大小为134177228</span></span>
<span class="line"><span>what        alloc  seq(w)  seq(r)  rand(w)  rand(r)  free</span></span>
<span class="line"><span>-----------------------------------------------------------</span></span>
<span class="line"><span>uint32_t    0      312     100     4480     4441     65</span></span>
<span class="line"><span>uint64_t    0      648     172     4482     4490     130</span></span>
<span class="line"><span>bad40_t     0      682     193     4573     4492     130</span></span>
<span class="line"><span>packed40_t  0      1164    552     6181     6176     130</span></span></code></pre></div><p>我们看到，位字段的额外开销是微不足道的，但是当以友好的方式线性访问数据时伴随位字段引用的操作符重载产生的开销则相当显著（大概有3倍）。在另一方面，随机访问产生的开销则无足轻重。</p><p>这些时间表明简单的使用64位整型会更好，因为它们在整体性能上要比位字段好（尽管占用更多的内存），但是显然它们并没有考虑随着数据集增大带来的缺页开销。一旦程序内存超过RAM大小，结果可能就不一样了（未亲自考证）。</p><hr>`,24)),t("p",null,[s[1]||(s[1]=a("via:",-1)),i(n,{href:"http://stackoverflow.com/questions/27705409/if-a-32-bit-integer-overflows-can-we-use-a-40-bit-structure-instead-of-a-64-bit/27705562#27705562"},{default:p(()=>[...s[0]||(s[0]=[a("stackoverflow",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"http://stackoverflow.com/users/572743/damon"},{default:p(()=>[...s[2]||(s[2]=[a("Damon",-1)])]),_:1}),i(n,{href:"http://stackoverflow.com/users/5801/michael-kohne"},{default:p(()=>[...s[3]||(s[3]=[a("Michael Kohne",-1)])]),_:1}),s[7]||(s[7]=a(" 译者：",-1)),i(n,{href:"https://github.com/KayGuoWhu"},{default:p(()=>[...s[4]||(s[4]=[a("KayGuoWhu",-1)])]),_:1}),s[8]||(s[8]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[11]||(s[11]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[9]||(s[9]=[a("LCTT",-1)])]),_:1}),s[12]||(s[12]=a(" 原创翻译，",-1)),i(n,{href:"http://linux.cn/"},{default:p(()=>[...s[10]||(s[10]=[a("Linux中国",-1)])]),_:1}),s[13]||(s[13]=a(" 荣誉推出",-1))])])}const m=l(o,[["render",d]]);export{C as __pageData,m as default};
